    // The symbol a tile shows when it has none of its own (shared/deck-model.js symbolOf).
    static func symbolOf(_ a: JSON?) -> String {
        let w = a?.str("what") ?? ""
        switch a?.str("k") ?? "" {
        case "keys": return "command"
        case "text": return "text"
        case "macro": return "macro"
        case "media": return (["playpause": "play", "next": "next", "prev": "prev", "stop": "stop"] as [String: String])[w] ?? "play"
        case "volume": return (["up": "volume", "down": "volumeDown", "set": "volume", "mute": "mute", "unmute": "volume", "toggle": "mute"] as [String: String])[w] ?? "volume"
        case "mic": return (["mute": "micOff", "unmute": "mic", "toggle": "micOff"] as [String: String])[w] ?? "micOff"
        case "output": return "speaker"
        case "input": return "mic"
        case "bt": return (["on": "bluetooth", "off": "bluetooth", "toggle": "bluetooth", "connect": "bluetooth", "disconnect": "bluetooth", "toggleconn": "bluetooth"] as [String: String])[w] ?? "bluetooth"
        case "bright": return (["up": "sun", "down": "sunDim", "set": "sun"] as [String: String])[w] ?? "sun"
        case "slider": return (["volume": "volume", "mic": "mic", "bright": "sun"] as [String: String])[w] ?? "volume"
        case "app": return "app"
        case "url": return "globe"
        case "open": return "folder"
        case "script": return "terminal"
        case "sys": return (["lock": "lock", "sleep": "sleep", "screenoff": "display", "desktop": "desktop", "switcher": "switcher", "overview": "windows", "screenshot": "camera", "shotarea": "crop", "darkmode": "moon", "dnd": "bellOff"] as [String: String])[w] ?? "lock"
        case "win": return (["left": "left", "right": "right", "top": "up", "bottom": "down", "max": "maximize", "center": "grid", "min": "minimize", "full": "maximize", "tl": "grid", "tr": "grid", "bl": "grid", "br": "grid", "third1": "grid", "third2": "grid", "third3": "grid", "nextdisplay": "display", "close": "none"] as [String: String])[w] ?? "left"
        case "clip": return (["copy": "copy", "cut": "cut", "paste": "paste", "send": "send"] as [String: String])[w] ?? "copy"
        case "nav": return (["page": "grid", "space": "windows", "next": "right", "prev": "left", "nextspace": "down", "prevspace": "up"] as [String: String])[w] ?? "grid"
        case "widget": return (["clock": "clock", "media": "play", "cpu": "cpu", "ram": "memory", "temp": "thermo"] as [String: String])[w] ?? "clock"
        case "none": return "none"
        default: return "none"
        }
    }
}
